type inventory struct {
	inventoryDo inventoryDo

	ALL              field.Asterisk
	ID               field.String
	ProductID        field.String
	Quantity         field.Int
	ReservedQuantity field.Int
	IsActive         field.Bool
	CreatedAt        field.Time
	UpdatedAt        field.Time
	Products         inventoryBelongsToProducts

	fieldMap map[string]field.Expr
}

func (i inventory) Table(newTableName string) *inventory {
	i.inventoryDo.UseTable(newTableName)
	return i.updateTableName(newTableName)
}

func (i inventory) As(alias string) *inventory {
	i.inventoryDo.DO = *(i.inventoryDo.As(alias).(*gen.DO))
	return i.updateTableName(alias)
}

func (i *inventory) updateTableName(table string) *inventory {
	i.ALL = field.NewAsterisk(table)
	i.ID = field.NewString(table, "id")
	i.ProductID = field.NewString(table, "product_id")
	i.Quantity = field.NewInt(table, "quantity")
	i.ReservedQuantity = field.NewInt(table, "reserved_quantity")
	i.IsActive = field.NewBool(table, "is_active")
	i.CreatedAt = field.NewTime(table, "created_at")
	i.UpdatedAt = field.NewTime(table, "updated_at")

	i.fillFieldMap()

	return i
}

func (i *inventory) WithContext(ctx context.Context) *inventoryDo {
	return i.inventoryDo.WithContext(ctx)
}

func (i inventory) TableName() string { return i.inventoryDo.TableName() }

func (i inventory) Alias() string { return i.inventoryDo.Alias() }

func (i inventory) Columns(cols ...field.Expr) gen.Columns { return i.inventoryDo.Columns(cols...) }

func (i *inventory) GetFieldByName(fieldName string) (field.OrderExpr, bool) {
	_f, ok := i.fieldMap[fieldName]
	if !ok || _f == nil {
		return nil, false
	}
	_oe, ok := _f.(field.OrderExpr)
	return _oe, ok
}

func (i *inventory) fillFieldMap() {
	i.fieldMap = make(map[string]field.Expr, 8)
	i.fieldMap["id"] = i.ID
	i.fieldMap["product_id"] = i.ProductID
	i.fieldMap["quantity"] = i.Quantity
	i.fieldMap["reserved_quantity"] = i.ReservedQuantity
	i.fieldMap["is_active"] = i.IsActive
	i.fieldMap["created_at"] = i.CreatedAt
	i.fieldMap["updated_at"] = i.UpdatedAt

}

func (i inventory) clone(db *gorm.DB) inventory {
	i.inventoryDo.ReplaceConnPool(db.Statement.ConnPool)
	i.Products.db = db.Session(&gorm.Session{Initialized: true})
	i.Products.db.Statement.ConnPool = db.Statement.ConnPool
	return i
}

func (i inventory) replaceDB(db *gorm.DB) inventory {
	i.inventoryDo.ReplaceDB(db)
	i.Products.db = db.Session(&gorm.Session{})
	return i
}

